@Override public Connectivity getConnectivity(){
  NetworkInfo networkInfo;
  try {
    networkInfo=platformConnectivityManager.getActiveNetworkInfo();
  }
 catch (  Throwable t) {
    networkInfo=null;
  }
  if (networkInfo != null) {
    boolean isConnected=networkInfo.isConnectedOrConnecting();
    boolean isMetered;
    boolean isWifi;
    try {
      isMetered=isNetworkMetered();
      isWifi=networkInfo.getType() == ConnectivityManager.TYPE_WIFI || hasNonCellularConnectivity();
    } catch (NullPointerException | IllegalStateException e) {
      isMetered = false;
      isWifi = false;
    }
    return new Connectivity(isConnected,isMetered,isWifi,null);
  }
 else {
    return Connectivity.DISCONNECTED;
  }
}
